package android.os;import java.util.*;public class Bundle{private final Map<String,Object> v=new HashMap<>();public void putString(String k,String x){v.put(k,x);}public String getString(String k){return (String)v.get(k);}public String getString(String k,String d){return v.containsKey(k)?getString(k):d;}public void putLong(String k,long x){v.put(k,x);}public long getLong(String k,long d){return v.containsKey(k)?((Number)v.get(k)).longValue():d;}public void putInt(String k,int x){v.put(k,x);}public int getInt(String k,int d){return v.containsKey(k)?((Number)v.get(k)).intValue():d;}public void putBoolean(String k,boolean x){v.put(k,x);}public boolean getBoolean(String k){return Boolean.TRUE.equals(v.get(k));}public void putParcelable(String k,Parcelable x){v.put(k,x);}public void putBundle(String k,Bundle b){v.put(k,b);}public Bundle getBundle(String k){return (Bundle)v.get(k);}public Object get(String k){return v.get(k);}}
